function twoSum(nums: number[], target: number): number[] {
    const seen = new Map<number, number>();     // 数值 -> 下标
    for (let i = 0; i < nums.length; i++) {
        const j = seen.get(target - nums[i]);   // 先查
        if (j !== undefined) {
            return [j, i];
        }
        seen.set(nums[i], i);                   // 再存
    }
    return [];
}

